<template>
  <div class="page">
    <el-card>
      <template #header><div class="header"><div><b>收件箱整理工作台</b><small>原始内容和附件始终保留；转换失败不会改变原记录状态</small></div><div><el-button @click="$router.push('/inbox')">返回收集</el-button><el-button type="primary" :disabled="!selected.length" @click="startBatch">批量整理 {{selected.length||''}}</el-button></div></div></template>
      <el-alert v-if="duplicates" :title="`发现 ${duplicates} 组可能重复内容，请在转换前核对`" type="warning" show-icon :closable="false"/>
      <div class="desktop"><el-table :data="items" @selection-change="selected=$event"><el-table-column type="selection" width="45"/><el-table-column prop="content" label="原始内容" min-width="260"/><el-table-column label="建议" width="110"><template #default="{row}"><el-tag>{{name(row.suggestedType)}}</el-tag></template></el-table-column><el-table-column label="附件" width="80"><template #default="{row}">{{row.attachments?.length||0}}</template></el-table-column><el-table-column label="操作" width="130"><template #default="{row}"><el-button type="primary" link @click="open(row)">补充字段并转换</el-button></template></el-table-column></el-table></div>
      <div class="mobile"><article v-for="item in items" :key="item.id"><el-checkbox :model-value="selected.some(x=>x.id===item.id)" @change="selectMobile(item,Boolean($event))"/><p>{{item.content}}</p><small>{{name(item.suggestedType)}} · {{item.attachments?.length||0}} 个附件</small><el-button type="primary" @click="open(item)">整理</el-button></article></div>
      <el-empty v-if="!items.length" description="没有待整理记录"/>
    </el-card>
    <el-dialog v-model="visible" title="补充转换字段" width="min(640px,94vw)" :before-close="beforeClose">
      <div v-if="current" class="original"><b>原始记录</b><p>{{current.content}}</p><small>{{current.attachments?.length||0}} 个附件将继续保留</small></div>
      <el-form label-position="top">
        <div class="grid"><el-form-item label="转换为"><el-select v-model="form.type"><el-option v-for="x in types" :key="x.value" :label="x.label" :value="x.value"/></el-select></el-form-item><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item></div>
        <template v-if="form.type==='TASK'"><div class="grid"><el-form-item label="生活/工作"><el-select v-model="form.taskType"><el-option label="生活" value="LIFE"/><el-option label="工作" value="WORK"/></el-select></el-form-item><el-form-item label="优先级"><el-select v-model="form.priority"><el-option label="低" value="LOW"/><el-option label="中" value="MEDIUM"/><el-option label="高" value="HIGH"/></el-select></el-form-item><el-form-item :label="form.taskType==='LIFE'?'生活分类':'工作类型'"><el-input v-model="form.category"/></el-form-item><el-form-item label="计划时间"><el-date-picker v-model="form.planTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item></div></template>
        <template v-if="form.type==='REMINDER'"><div class="grid"><el-form-item label="提醒时间"><el-date-picker v-model="form.remindTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="通知通道 ID（可选）"><el-input-number v-model="form.channelId" :min="1"/></el-form-item></div></template>
        <template v-if="form.type==='EXPENSE'"><div class="grid"><el-form-item label="账户"><el-select v-model="form.accountId"><el-option v-for="x in accounts" :key="x.id" :label="x.accountName" :value="x.id"/></el-select></el-form-item><el-form-item label="金额"><el-input-number v-model="form.amount" :min="0" :precision="2"/></el-form-item><el-form-item label="方向"><el-select v-model="form.direction"><el-option label="支出" value="EXPENSE"/><el-option label="收入" value="INCOME"/></el-select></el-form-item><el-form-item label="分类"><el-select v-model="form.categoryId" clearable><el-option v-for="x in categories" :key="x.id" :label="x.categoryName" :value="x.id"/></el-select></el-form-item><el-form-item label="交易时间"><el-date-picker v-model="form.transactionTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item></div></template>
        <template v-if="form.type==='LEARNING'"><div class="grid"><el-form-item label="学习计划"><el-select v-model="form.learningPlanId"><el-option v-for="x in plans" :key="x.id" :label="x.title" :value="x.id"/></el-select></el-form-item><el-form-item label="学习分钟"><el-input-number v-model="form.durationMinutes" :min="0"/></el-form-item></div></template>
        <el-form-item label="补充说明"><el-input v-model="form.note" type="textarea" :rows="3"/></el-form-item>
      </el-form>
      <template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="convert">确认并创建业务记录</el-button></template>
    </el-dialog>
    <el-dialog v-model="resultVisible" title="转换成功" width="min(430px,92vw)"><el-result icon="success" title="业务记录已创建" :sub-title="`类型 ${result?.convertedType} · ID ${result?.convertedId} · 版本 ${result?.version}`"><template #extra><el-button @click="undo">撤销转换</el-button><el-button type="primary" @click="goResult">查看结果</el-button></template></el-result></el-dialog>
  </div>
</template>
<script setup lang="ts">import{ElMessage,ElMessageBox}from'element-plus';import{computed,onMounted,reactive,ref,watch}from'vue';import{useRouter}from'vue-router';import{listInbox,type InboxItem}from'@/api/productivity';import{convertInbox,undoInboxConversion,type ConversionResult}from'@/api/inboxConversion';import{listFinanceAccounts,listFinanceCategories,type FinanceAccount,type FinanceCategory}from'@/api/finance';import{listPlans,type LearningPlan}from'@/api/learning';const router=useRouter(),items=ref<InboxItem[]>([]),selected=ref<InboxItem[]>([]),current=ref<InboxItem>(),visible=ref(false),resultVisible=ref(false),result=ref<ConversionResult>(),saving=ref(false),dirty=ref(false),accounts=ref<FinanceAccount[]>([]),categories=ref<FinanceCategory[]>([]),plans=ref<LearningPlan[]>([]);const types=[['TASK','任务'],['REMINDER','提醒'],['EXPENSE','消费'],['LEARNING','学习记录'],['NOTE','普通笔记']].map(([value,label])=>({value,label}));const form=reactive<any>({type:'NOTE',title:'',taskType:'LIFE',priority:'MEDIUM',category:'日常',planTime:'',remindTime:'',channelId:undefined,accountId:undefined,categoryId:undefined,amount:undefined,direction:'EXPENSE',transactionTime:'',learningPlanId:undefined,durationMinutes:0,note:''});const duplicates=computed(()=>{const map=new Map<string,number>();items.value.forEach(x=>{const key=x.content.trim().toLowerCase();map.set(key,(map.get(key)||0)+1)});return[...map.values()].filter(x=>x>1).length;});async function load(){items.value=(await listInbox('PENDING')).data;[accounts.value,categories.value,plans.value]=await Promise.all([listFinanceAccounts().then(x=>x.data),listFinanceCategories().then(x=>x.data),listPlans().then(x=>x.data)]);}function open(item:InboxItem){current.value=item;Object.assign(form,{type:item.suggestedType||'NOTE',title:item.content.slice(0,80),taskType:'LIFE',priority:'MEDIUM',category:'日常',planTime:'',remindTime:'',channelId:undefined,accountId:accounts.value[0]?.id,categoryId:undefined,amount:undefined,direction:'EXPENSE',transactionTime:item.recordedAt||item.createdAt,learningPlanId:plans.value[0]?.id,durationMinutes:0,note:item.remark||''});dirty.value=false;visible.value=true;}async function convert(){if(!current.value)return;saving.value=true;try{const payload={...form,workType:form.taskType==='WORK'?form.category:undefined,category:form.taskType==='LIFE'?form.category:undefined};result.value=(await convertInbox(current.value.id,payload)).data;dirty.value=false;visible.value=false;resultVisible.value=true;items.value=items.value.filter(x=>x.id!==current.value?.id);selected.value=selected.value.filter(x=>x.id!==current.value?.id);ElMessage.success('已创建业务记录，原始内容和附件已保留');}finally{saving.value=false;}}async function undo(){if(!result.value)return;await undoInboxConversion(result.value.inboxId);resultVisible.value=false;ElMessage.success('已撤销追踪关系，已创建的业务记录未删除');await load();}function goResult(){if(result.value)void router.push(result.value.route);}function startBatch(){if(selected.value[0])open(selected.value[0]);}function selectMobile(item:InboxItem,checked:boolean){selected.value=checked?[...selected.value,item]:selected.value.filter(x=>x.id!==item.id);}function beforeClose(done:()=>void){if(!dirty.value)return done();ElMessageBox.confirm('转换字段尚未保存，确定关闭？','防误关闭').then(done).catch(()=>{});}const name=(v:string)=>types.find(x=>x.value===v)?.label||v;watch(form,()=>{if(visible.value)dirty.value=true;},{deep:true});onMounted(load);</script>
<style scoped>.page{display:flex;flex-direction:column;gap:14px}.header{display:flex;align-items:center;justify-content:space-between;gap:12px}.header>div:last-child{display:flex;gap:8px}.header small,.original small{display:block;margin-top:4px;color:#718096}.mobile{display:none}.original{margin-bottom:16px;padding:14px;background:#f7f9fc;border-radius:12px}.original p{white-space:pre-wrap}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}@media(max-width:768px){.desktop{display:none}.mobile{display:flex;flex-direction:column;gap:10px}.mobile article{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:10px;padding:14px;border:1px solid #e5eaf1;border-radius:12px}.mobile p{margin:0}.mobile small{grid-column:2;color:#718096}.header{align-items:flex-start;flex-direction:column}.grid{grid-template-columns:1fr}}</style>
